<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Audit log | Digital Library</title><link rel="stylesheet" href="/assets/app.css"></head><body><header class="site-header"><a class="brand" href="/dashboard">Digital Library</a><nav><a href="/">Catalog</a></nav></header><main class="container"><p class="eyebrow">Administration</p><h1>Audit log</h1><p class="muted"><?= e((string) $audit['total']) ?> recorded events</p><?php if ($audit['logs'] === []): ?><div class="empty-state"><h2>No audit events</h2></div><?php else: ?><div class="audit-list"><?php foreach ($audit['logs'] as $log): ?><article class="book-card"><p class="eyebrow"><?= e($log['action']) ?></p><h2><?= e($log['user_name'] ?: 'System') ?></h2><p><?= e($log['entity_type'] ?: 'general') ?> <?= e((string) ($log['entity_id'] ?: '')) ?></p><p class="muted"><?= e($log['created_at']) ?> · <?= e($log['ip_address'] ?: 'unknown IP') ?></p></article><?php endforeach; ?></div><?php if ($audit['pages'] > 1): ?><nav class="pagination" aria-label="Audit pages"><?php for ($page = 1; $page <= $audit['pages']; $page++): ?><a <?= $page === $audit['page'] ? 'aria-current="page"' : '' ?> href="/admin/audit?page=<?= e((string) $page) ?>"><?= e((string) $page) ?></a><?php endfor; ?></nav><?php endif; ?><?php endif; ?></main></body></html>